const $=(s,r=document)=>r.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={eye:'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',home:'m3 10 9-7 9 7v10H3Z M9 20v-7h6v7',spark:'m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z',briefcase:'M3 7h18v13H3z M8 7V4h8v3 M3 12q9 5 18 0 M12 12v4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2',group:'M15 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0 M5 21v-3a7 7 0 0 1 14 0v3 M19 4a3 3 0 0 1 0 6 M21 14q2 1 2 5',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4Z M10 21h4',check:'m5 12 4 4L19 6',arrow:'M5 12h14m-5-5 5 5-5 5',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z m-4 10 3 3 5-6',book:'M3 4h7q2 0 2 2 0-2 2-2h7v16h-7q-2 0-2 2 0-2-2-2H3Z M12 6v16',plus:'M12 4v16M4 12h16',code:'m8 5-6 7 6 7 m8-14 6 7-6 7 M14 3l-4 18',logout:'M9 3H3v18h6 M9 12h12m-5-5 5 5-5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`;
const link=(u,t,cls='btn',i='arrow')=>`<a class="${cls}" href="${u}">${t}${icon(i)}</a>`;
const title=(k,h,p='')=>`<div class="page-title"><div class="eyebrow">${k}</div><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${label}${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;
let config={skills:[]},user=null,opportunities=[],notifications=[],applications=[],directory=[],management=null,authRole='student',authMode='login',filter='All',search='',renderId=0;
const staff=()=>user&&user.role!=='student';const current=()=>location.pathname.replace(/\/$/,'')||'/';
async function api(url,method='GET',data){const r=await fetch('/api'+url,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await r.json()}catch{throw new Error('The backend is unavailable. Restart the app server.')}if(!r.ok)throw Object.assign(new Error(result.error||'Request failed.'),{status:r.status});return result}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(html){$('#modal').innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button>${html}`;$('#modal').showModal()}
function tags(list){return list.map(s=>`<span class="pill">${esc(s)}</span>`).join('')}
function skillsPicker(selected=[],name='skills'){return `<fieldset class="skill-picker"><legend>Select the skills you have or want to explore</legend><div class="skill-options">${config.skills.map(s=>`<label><input type="checkbox" name="${name}" value="${esc(s)}" ${selected.includes(s)?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div></fieldset>`}
function shell(){const p=current();let nav=staff()?[['/','Overview','home'],['/students','Students','group'],['/opportunities','Opportunities','briefcase'],['/applications','Applications','book'],[user.role==='management'?'/management':'/profile',user.role==='management'?'Manage':'Profile',user.role==='management'?'shield':'user']]:[['/','Home','home'],['/discover','Discover','spark'],['/opportunities','Opportunities','briefcase'],['/inbox','Inbox','bell'],['/profile','Profile','user']];$('#header').innerHTML=`<div class="wrap header-inner"><a href="/" class="brand" aria-label="UNSEEN Discover home"><span class="brand-mark">${icon('eye')}</span>unseen<span class="brand-period">.</span><span class="brand-sub">DISCOVER</span></a><span class="identity">${user?`${esc(user.name.split(' ')[0])}<span class="role-dot"></span>${esc(user.role)}`:'THE STUDENT OPPORTUNITY SPACE'}</span></div>`;$('#dock').innerHTML=nav.map(([u,t,i])=>`<a href="${u}" class="${p===u?'active':''}" ${p===u?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${u==='/inbox'&&notifications.some(n=>!n.read)?'<b class="unread-dot" aria-label="Unread messages"></b>':''}</a>`).join('');$('#footer').innerHTML='<div class="wrap footer-note">UNSEEN DISCOVER <span>Every student has something worth discovering.</span></div>'}
function publicHome(){return `<div class="wrap"><section class="discover-hero"><div><div class="eyebrow">YOUR SKILLS. YOUR NEXT CHAPTER.</div><h1>You have<br>more to <span class="highlight">offer.</span></h1><p>Find what you’re good at. Meet the people who need it.<br>A dedicated space for students, teachers, and possibilities.</p><div class="actions">${link('/login?role=student','Find my potential','btn dark','spark')}${link('/login?role=teacher','I’m a teacher','text-link')}</div><div class="hero-caption">${icon('check')} No rankings. No familiar faces first. Just a chance.</div></div><div class="potential-art"><div class="art-orbit"></div><div class="art-orbit inner"></div><div class="potential-core">${icon('spark')}<span>YOUR<br>POTENTIAL</span></div><div class="floating-skill skill-a">${icon('code')} Coding</div><div class="floating-skill skill-b">${icon('group')} Leadership</div><div class="floating-skill skill-c">${icon('book')} Creative thinking</div><div class="art-caption">A FIRST STEP CAN CHANGE EVERYTHING.</div></div></section><div class="entry-grid"><a href="/login?role=student" class="entry-card"><span class="icon-box">${icon('user')}</span><div><h3>For students</h3><p>Discover skills. Find your opportunity.</p></div>${icon('arrow')}</a><a href="/login?role=teacher" class="entry-card"><span class="icon-box">${icon('book')}</span><div><h3>For teachers</h3><p>Find talent. Build a great team.</p></div>${icon('arrow')}</a><a href="/login?role=management" class="entry-card"><span class="icon-box">${icon('shield')}</span><div><h3>For management</h3><p>Connect your whole institution.</p></div>${icon('arrow')}</a></div><section class="section"><div class="section-head"><div><div class="eyebrow">FROM INTEREST TO OPPORTUNITY</div><h2>Good things happen<br>when the right people connect.</h2></div><p>A coding webinar reaches coding students. A creative project reaches creative minds. Every suggestion has a reason.</p></div><div class="grid three"><div class="step"><span>01 / DISCOVER</span><h3>Start with your interests.</h3><p>Select your skills or explore them through a short guided reflection.</p></div><div class="step"><span>02 / CONNECT</span><h3>Find your kind of opportunity.</h3><p>Get in-app suggestions for webinars, contests, projects, and student roles.</p></div><div class="step"><span>03 / TAKE PART</span><h3>Turn potential into practice.</h3><p>Apply, receive an invitation, and let your teacher help you take the next step.</p></div></div></section>${config.setupRequired?`<div class="setup-callout"><div><h3>Bringing your institution onboard?</h3><p>Create the first management account, then invite teachers and students.</p></div>${link('/setup','Set up institution','btn','shield')}</div>`:''}</div>`}
function authPage(){const q=new URLSearchParams(location.search);authRole=['student','teacher','management'].includes(q.get('role'))?q.get('role'):authRole;const registering=authMode==='register';return `<div class="wrap auth-layout"><section class="auth-story"><div class="eyebrow">UNSEEN DISCOVER</div><h1>Your next<br>chapter<br>starts <span>here.</span></h1><p>One institution. Many possibilities.<br>Sign in to a space built around you.</p><div class="auth-orb">${icon('spark')}</div></section><section class="card auth-card"><span class="eyebrow">${esc(config.institution||'YOUR INSTITUTION')}</span><h2>${registering?'Make yourself seen.':'Good to see you.'}</h2><p style="margin:12px 0 25px">${registering?'Create your account to get started.':'Choose your role and pick up where you left off.'}</p><div class="role-selector">${['student','teacher','management'].map(r=>`<button class="${authRole===r?'active':''}" data-role="${r}">${icon(r==='student'?'user':r==='teacher'?'book':'shield')}<span>${r[0].toUpperCase()+r.slice(1)}</span></button>`).join('')}</div>${config.setupRequired?`<div class="notice">This institution hasn’t been set up yet. The first management account creates the workspace.</div>${link('/setup','Set up institution')}`:`<form id="auth-form">${registering?field('Your name','name','text','','required minlength="2" maxlength="80" autocomplete="name"'):''}${field('Email address','email','email','','required autocomplete="email"')}${field('Password','password','password','','required minlength="10" maxlength="128" autocomplete="'+(registering?'new-password':'current-password')+'"')}${registering?field(authRole==='student'?'Institution join code':'Your staff invitation code','code','text','','required autocomplete="off"'):''}<div class="form-error" role="alert"></div><button class="btn dark full-button" type="submit">${registering?'Create account':'Sign in'} ${icon('arrow')}</button></form><p class="helper">${registering?(authRole==='student'?'Ask management for your institution join code.':'Staff accounts require an email-bound invitation from management.'):'Forgot your password? Ask the local server administrator for help; email recovery is not configured.'}</p><button class="auth-toggle" data-action="auth-toggle">${registering?'Already have an account? Sign in':'New here? Create an account'}</button>`}</section></div>`}
function setupPage(){return `<div class="wrap narrow">${title('INSTITUTION SETUP','A place for every student.','Create the first management account. You’ll then receive a student join code and can invite teachers.')}<section class="card"><form id="setup-form">${field('Institution name','institution','text','','required minlength="2" maxlength="120"')}${field('Your name','name','text','','required minlength="2" maxlength="80"')}${field('Management email','email','email','','required')}${field('Password','password','password','','required minlength="10" maxlength="128" autocomplete="new-password"')}<p class="helper" style="margin-bottom:20px">Use at least 10 characters. This account controls staff access.</p><div class="form-error" role="alert"></div><button class="btn dark" type="submit">Create institution ${icon('arrow')}</button></form></section></div>`}
function gated(){return `<div class="wrap narrow">${title('YOUR PERSONAL SPACE','Let’s get you signed in.','Your skills, suggestions, and applications are connected to your own account.')}<div class="card"><h3>Choose your space</h3><div class="list" style="margin-top:25px">${link('/login?role=student','Student sign in','btn dark','user')}${link('/login?role=teacher','Teacher sign in','btn outline','book')}${link('/login?role=management','Management sign in','btn outline','shield')}</div></div></div>`}
function dashboard(){const relevant=opportunities.filter(o=>o.status==='open'&&(!o.deadline||o.deadline>=new Date().toISOString().slice(0,10))&&(staff()?o.owner===user.id:o.match.length));return `<div class="wrap">${title(esc(config.institution)+' / '+esc(user.role)+' SPACE',`Hello, ${esc(user.name.split(' ')[0])}.`,staff()?'Give someone new a chance to shine.':'Your interests are a starting point. Let’s see where they take you.')}<div class="dashboard-banner"><div><span class="eyebrow">${staff()?'OPEN A DOOR':'YOUR NEXT SMALL STEP'}</span><h2>${staff()?'The right skill could be<br>closer than you think.':user.skills.length?'Your skills deserve<br>a place to grow.':'What comes naturally<br>to you?'}</h2><p>${staff()?'Post an opportunity. We’ll suggest it to students with matching skills.':'Select your skills to start receiving relevant opportunities from your teachers.'}</p>${link(staff()?'/opportunities/new':user.skills.length?'/opportunities':'/profile',staff()?'Create an opportunity':user.skills.length?'Explore my opportunities':'Choose my skills','btn dark')}</div><div class="banner-art">${icon(staff()?'group':'spark')}</div></div><div class="stats"><div class="stat"><strong>${staff()?opportunities.filter(o=>o.owner===user.id).length:user.skills.length}</strong><span>${staff()?'Your opportunities':'Selected skills'}</span></div><div class="stat"><strong>${applications.length}</strong><span>${staff()?'Applications to review':'Your applications'}</span></div><div class="stat"><strong>${staff()?directory.length:notifications.filter(n=>!n.read).length}</strong><span>${staff()?'Discoverable students':'New updates'}</span></div></div><div class="section-head"><div><div class="eyebrow">${staff()?'YOUR OPPORTUNITIES':'MATCHED TO YOUR INTERESTS'}</div><h2>${staff()?'Make something happen.':'A chance to put it into practice.'}</h2></div>${link('/opportunities','View all','text-link')}</div><div class="grid three">${relevant.length?relevant.slice(0,3).map(opportunityCard).join(''):`<div class="empty full">${staff()?'Your first opportunity starts with an idea. Create a webinar, contest, project, or student role.':user.skills.length?'No matching opportunities yet. Your teachers can publish something new at any time.':'Choose your skills to get relevant suggestions. You can still explore all opportunities.'}</div>`}</div>${!staff()?`<div class="section-head" style="margin-top:40px"><h3>Your applications</h3>${link('/applications','View progress','text-link')}</div>${applicationList(applications.slice(0,3))}`:''}</div>`}
function opportunityCard(o){const closed=o.status==='closed'||(o.deadline&&o.deadline<new Date().toISOString().slice(0,10));return `<article class="card opportunity-card"><div class="card-top"><span class="icon-box">${icon(o.type==='Webinar'?'book':o.type==='Contest'?'code':'briefcase')}</span><span class="pill ${closed?'':'lime'}">${closed?'Closed':esc(o.type)}</span></div><span class="meta">Posted by ${esc(o.owner_name)}</span><h3>${esc(o.title)}</h3><p class="clamp">${esc(o.description)}</p><div class="badge-line">${tags(o.skills)}</div>${o.match.length?`<p class="match-reason">${icon('check')} Matches ${esc(o.match.join(', '))}</p>`:''}<div class="meta">${o.deadline?'Closes '+esc(o.deadline):'No fixed deadline'}</div><button class="btn outline" data-opportunity="${o.id}">${staff()?'View opportunity':o.application?esc(o.application):'Explore opportunity'} ${icon('arrow')}</button></article>`}
function opportunitiesPage(){return `<div class="wrap">${title('WEBINARS · CONTESTS · PROJECTS · HIRING','Find your place to contribute.',staff()?'Reach students through their chosen skills. Publish an opportunity and send relevant in-app suggestions.':'Explore every opportunity. Skill matches are suggestions, never a barrier to applying.')}<div class="section-head">${staff()?link('/opportunities/new','Create opportunity','btn dark','plus'):'<span class="pill">All students are welcome to explore</span>'}<input id="search-opportunities" class="search" style="max-width:340px" placeholder="Search opportunities" aria-label="Search opportunities" value="${esc(search)}"></div><div class="toolbar">${['All','For me','Webinar','Contest','Project','Hiring'].filter(t=>t!=='For me'||!staff()).map(t=>`<button class="filter ${filter===t?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div id="opportunity-list" class="grid three">${filteredOpportunities()}</div></div>`}
function filteredOpportunities(){const items=opportunities.filter(o=>(filter==='All'||filter==='For me'&&o.match.length||o.type===filter)&&`${o.title} ${o.skills.join(' ')} ${o.description}`.toLowerCase().includes(search.toLowerCase()));return items.map(opportunityCard).join('')||'<div class="empty full">No opportunities here yet. Try another filter or check back after your teacher posts one.</div>'}
function createOpportunity(){return `<div class="wrap">${title('CREATE AN OPPORTUNITY','The next chance starts with you.','Choose the relevant skills. Matching students will receive an in-app suggestion when you publish.')}<div class="workspace"><section class="card"><form id="opportunity-form">${field('Opportunity title','title','text','','required minlength="3" maxlength="120" placeholder="e.g. Build your first website — coding webinar"')}<div class="two-fields"><label class="field">Type<select name="type"><option>Webinar</option><option>Contest</option><option>Project</option><option>Hiring</option></select></label>${field('Closing date (optional)','deadline','date','','min="'+new Date().toISOString().slice(0,10)+'"')}</div>${field('What will students do? Include time, place, and how to participate.','description','textarea','','required minlength="20" maxlength="4000"')}${skillsPicker()}<div class="form-error" role="alert"></div><button class="btn dark" type="submit">Publish & suggest to matching students ${icon('arrow')}</button></form></section><aside class="card"><span class="icon-box">${icon('spark')}</span><h3 style="margin-top:20px">Relevant, not exclusive.</h3><p>Select Coding for a coding webinar, or Event planning for an organizing team. Every matching student gets one suggestion in their inbox.</p><p style="margin-top:18px">All students can still browse and apply. Teachers make selection decisions after reviewing applications.</p><div class="notice" style="margin-top:25px">Suggestions are delivered inside this app. Email and SMS are not connected.</div></aside></div></div>`}
function profilePage(){return `<div class="wrap">${title('YOUR PROFILE','More than a list of skills.','Build a profile that feels like you. Change your interests whenever you want.')}<div class="workspace"><section class="card"><form id="profile-form">${field('Name','name','text',user.name,'required minlength="2" maxlength="80"')}${field('Course or department','course','text',user.course,'maxlength="120"')}${field('Tell us about your interests and experience','bio','textarea',user.bio,'maxlength="2000"')}${user.role==='student'?`${skillsPicker(user.skills)}<label class="checkbox"><input name="discoverable" type="checkbox" ${user.discoverable?'checked':''}>Let teachers find my name, course, bio, and selected skills in the student directory.</label><p class="helper">You can receive skill-based suggestions without appearing in the directory. Teachers see your application when you choose to apply.</p>`:''}<div class="form-error" role="alert"></div><button class="btn dark" type="submit" style="margin-top:20px">Save profile ${icon('check')}</button></form></section><aside class="card"><div class="person"><div class="avatar">${esc(user.name.charAt(0))}</div><div><h3>${esc(user.name)}</h3><p>${esc(user.role)} · ${esc(config.institution)}</p></div></div><div class="badge-line">${tags(user.skills)}</div><p>${esc(user.email)}</p>${user.role==='student'?`<div style="margin-top:25px">${link('/discover','Not sure about your skills?','text-link','spark')}</div><div style="margin-top:20px">${link('/applications','View my applications','text-link','briefcase')}</div>`:''}<button class="btn outline" style="margin-top:30px" data-action="logout">Sign out ${icon('logout')}</button></aside></div></div>`}
function discoverPage(){return `<div class="wrap">${title('A LITTLE CURIOSITY GOES A LONG WAY','What’s waiting to be discovered?','You don’t have to know what you’re good at yet. Start with what you enjoy.')}<div class="workspace"><section class="card"><span class="pill lime">EXPLORE, DON’T LABEL</span><h3 class="question">What do you enjoy doing—and what do people ask you for help with?</h3><form id="discover-form">${field('Your reflection','answers','textarea','','required minlength="15" maxlength="6000" placeholder="Maybe you enjoy fixing things, explaining ideas, coding, organizing events, or noticing details…"')}${config.aiEnabled?'<label class="checkbox"><input type="checkbox" name="useAI">Use AI assistance. Send only this reflection to OpenAI; avoid personal or sensitive details.</label>':'<p class="helper">Guided mode is available now. AI assistance activates when the server owner configures an API key and model.</p>'}<div class="form-error" role="alert"></div><button class="btn dark" type="submit" style="margin-top:20px">Explore possible skills ${icon('spark')}</button></form><div id="discovery-result" aria-live="polite"></div></section><aside class="card"><h3>Your potential isn’t a score.</h3><ul class="check-list"><li>${icon('check')}Suggestions are possibilities to explore.</li><li>${icon('check')}You choose what to add to your profile.</li><li>${icon('check')}Nothing here makes hiring decisions.</li><li>${icon('check')}You can select your skills directly anytime.</li></ul>${link('/profile','Choose my skills','text-link')}</aside></div></div>`}
function inboxPage(){return `<div class="wrap">${title('YOUR UPDATES','A door might be opening.','Skill matches, teacher invitations, and application updates—all in one place.')}<div class="section-head"><span class="pill">${notifications.filter(n=>!n.read).length} unread</span><button class="btn outline small" data-action="read-all">Mark all read ${icon('check')}</button></div><div class="list">${notifications.map(n=>`<article class="notification ${n.read?'':'unread'}"><span class="icon-box">${icon(n.kind==='invitation'?'user':'bell')}</span><div><span class="meta">${n.kind==='suggestion'?'SKILL MATCH':n.kind==='invitation'?'TEACHER INVITATION':'APPLICATION UPDATE'} · ${new Date(n.created).toLocaleDateString()}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.opportunity?`<button class="text-button" data-opportunity="${n.opportunity}">View opportunity ${icon('arrow')}</button>`:''}</div></article>`).join('')||'<div class="empty">No updates yet. Select your skills and we’ll show matching opportunities here when teachers publish them.</div>'}</div></div>`}
function studentsPage(){return `<div class="wrap">${title('THE STUDENT DIRECTORY','Find the skill behind the name.','Browse students who have chosen to be discoverable. Invite them to an opportunity and start a conversation.')}<input id="search-students" class="search" style="max-width:450px;margin-bottom:28px" placeholder="Search by name, course, or skill" aria-label="Search students"><div id="student-list" class="grid three">${studentCards()}</div></div>`}
function studentCards(q=''){return directory.filter(s=>`${s.name} ${s.course} ${s.skills.join(' ')}`.toLowerCase().includes(q.toLowerCase())).map(s=>`<article class="card opportunity-card"><div class="person"><div class="avatar">${esc(s.name.charAt(0))}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.course||'Student')}</p></div></div><p>${esc(s.bio||'Still exploring what comes next.')}</p><div class="badge-line">${tags(s.skills)}</div><button class="btn outline" data-invite-student="${s.id}">Invite to an opportunity ${icon('arrow')}</button></article>`).join('')||'<div class="empty full">No discoverable students match. Students appear here after opting in on their profile.</div>'}
function applicationList(items){return items.map(a=>`<article class="application card"><div><span class="pill">${esc(a.type)}</span><h3 style="margin:12px 0 8px">${esc(a.title)}</h3>${staff()?`<p>From ${esc(a.student_name)}</p>`:''}<p style="margin-top:10px">${esc(a.message)}</p></div><div>${staff()?`<label class="field">Review status<select data-review="${a.id}">${['Applied','Under review','Invited to talk','Selected','Not selected'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`:`<span class="pill lime">${esc(a.status)}</span>`}<span class="meta">${new Date(a.created).toLocaleDateString()}</span></div></article>`).join('')||'<div class="empty">No applications yet.</div>'}
function applicationsPage(){return `<div class="wrap">${title(staff()?'REVIEW APPLICATIONS':'YOUR APPLICATIONS',staff()?'See the person. Then decide.':'Keep an eye on your next chapter.',staff()?'Review each application thoughtfully. Decisions are made by you, never by an automated score.':'Your applications and teacher responses are saved to your account.')}<div class="list">${applicationList(applications)}</div></div>`}
function managementPage(){return `<div class="wrap">${title('MANAGEMENT / '+esc(management.institution),'Connect your institution.','Invite your teachers, welcome students, and manage access from one place.')}<div class="workspace"><section><div class="card"><h3>Student join code</h3><p>Share this code with students in your institution.</p><code class="join-code">${esc(management.joinCode)}</code><button class="btn outline small" data-action="rotate-code">Generate new code</button><p class="helper">A new code replaces the previous one. Existing accounts stay active.</p></div><div class="card" style="margin-top:20px"><h3>Invite a staff member</h3><p style="margin-bottom:20px">Each invitation is bound to an email, works once, and expires in 48 hours.</p><form id="staff-invite-form">${field('Staff email','email','email','','required')}<label class="field">Role<select name="role"><option value="teacher">Teacher</option><option value="management">Management</option></select></label><div class="form-error" role="alert"></div><button class="btn dark" type="submit">Create invitation ${icon('plus')}</button></form><div id="invitation-result" aria-live="polite"></div></div></section><aside class="card"><h3>People in your institution</h3><div class="list" style="margin-top:20px">${management.users.map(u=>`<div class="row"><div><strong>${esc(u.name)}</strong><p>${esc(u.email)}</p></div><span class="pill">${esc(u.role)}</span></div>`).join('')}</div><div class="notice" style="margin-top:20px">${config.aiEnabled?'AI assistance is configured on the server.':'AI is optional. Configure OPENAI_API_KEY and OPENAI_MODEL on the server to enable it. Never paste keys into student or teacher forms.'}</div>${link('/profile','My account','text-link','user')}<button class="btn outline" style="margin-top:20px" data-action="logout">Sign out ${icon('logout')}</button></aside></div></div>`}
function loginDestination(){const next=new URLSearchParams(location.search).get('next');return ['/','/inbox','/profile','/discover','/opportunities','/applications','/students','/management','/opportunities/new'].includes(next)?next:null}
function loginUrl(next=current()){return '/login?role='+encodeURIComponent(authRole)+'&next='+encodeURIComponent(next)}
function clearAccountData(){opportunities=[];notifications=[];applications=[];directory=[];management=null}
function announceSession(){try{localStorage.setItem('unseen-session-change',String(Date.now())+Math.random())}catch{}}
async function refresh(account){const [o,n,a]=await Promise.all([api('/opportunities'),api('/notifications'),api('/applications')]);const result={opportunities:o.opportunities,notifications:n.notifications,applications:a.applications,directory:[],management:null};if(account.role!=='student')result.directory=(await api('/students')).students;if(account.role==='management')result.management=await api('/management');return result}
async function render(){const id=++renderId;let p=current();$('#main').innerHTML='<div class="wrap page-title"><p role="status">Opening your space…</p></div>';try{
const [latestConfig,session]=await Promise.all([api('/config'),api('/me')]);if(id!==renderId)return;
config=latestConfig;if(user?.id!==session.user?.id)clearAccountData();user=session.user;
if(config.setupRequired){if(p!=='/'&&p!=='/setup'){history.replaceState({},'','/setup');p='/setup'}}
else if(!user&&p!=='/'&&p!=='/login'){history.replaceState({},'',loginUrl(p));p='/login';authMode='login'}
else if(user&&(p==='/login'||p==='/setup')){const destination=loginDestination()||(p==='/setup'&&user.role==='management'?'/management':'/');history.replaceState({},'',destination);p=destination}
if(user){const data=await refresh(user);if(id!==renderId)return;({opportunities,notifications,applications,directory,management}=data)}
shell();let html;
if(p==='/login')html=authPage();else if(p==='/setup')html=setupPage();else if(p==='/'&&!user)html=publicHome();else if(!user)html=authPage();else{const pages={'/':dashboard,'/profile':profilePage,'/opportunities':opportunitiesPage,'/inbox':inboxPage,'/applications':applicationsPage};if(p==='/discover')html=user.role==='student'?discoverPage():studentsPage();else if(p==='/students')html=staff()?studentsPage():'<div class="wrap">'+title('TEACHER SPACE','This directory is for teachers.')+'</div>';else if(p==='/management')html=user.role==='management'?managementPage():'<div class="wrap">'+title('MANAGEMENT SPACE','Management access is required.')+'</div>';else if(p==='/opportunities/new')html=staff()?createOpportunity():'<div class="wrap">'+title('TEACHER SPACE','Teachers create opportunities here.')+'</div>';else html=pages[p]?pages[p]():dashboard()}
if(id!==renderId)return;$('#main').innerHTML=html;document.title='UNSEEN Discover — Skills & Opportunities';
}catch(e){if(id!==renderId)return;if(e.status===401){user=null;clearAccountData();authMode='login';history.replaceState({},'',loginUrl(p));shell();$('#main').innerHTML=authPage();toast('Your session has ended. Please sign in again.')}else{$('#main').innerHTML='<div class="wrap">'+title('CONNECTION ISSUE','Let’s try that again.',esc(e.message))+'<button class="btn" data-action="retry">Retry</button></div>'}}}
function go(href){history.pushState({},'',href);filter='All';search='';const pending=render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});return pending}
async function reconcileSession(){const version=renderId;try{const [session,latestConfig]=await Promise.all([api('/me'),api('/config')]);if(version!==renderId)return;if(user?.id!==session.user?.id||config.setupRequired!==latestConfig.setupRequired){if($('#modal').open)$('#modal').close();await render()}}catch{}}
function showOpportunity(id){const o=opportunities.find(x=>x.id===id);if(!o){toast('This opportunity is no longer available.');return}const owned=staff()&&(o.owner===user.id||user.role==='management');const closed=o.status!=='open'||(o.deadline&&o.deadline<new Date().toISOString().slice(0,10));modal(`<span class="pill lime">${esc(o.type)}</span><h3 style="margin-top:20px">${esc(o.title)}</h3><p class="preserve">${esc(o.description)}</p><div class="badge-line">${tags(o.skills)}</div><p class="helper">Posted by ${esc(o.owner_name)}${o.deadline?' · Closes '+esc(o.deadline):''}</p>${owned?`<div class="inline-buttons" style="margin-top:25px"><button class="btn dark" data-suggest="${o.id}" ${closed?'disabled':''}>Suggest to matching students</button><button class="btn outline" data-toggle-opportunity="${o.id}" data-status="${o.status==='open'?'closed':'open'}">${o.status==='open'?'Close':'Reopen'} opportunity</button></div>`:staff()?'<p class="helper">You can browse this opportunity. Only its owner or management can manage it.</p>':o.application?`<div class="result"><p>Your application: <strong>${esc(o.application)}</strong></p></div>`:closed?'<div class="notice">This opportunity is closed.</div>':`<form id="apply-form" data-id="${o.id}" style="margin-top:25px">${field('What interests you about this opportunity?','message','textarea','','required minlength="15" maxlength="3000"')}<div class="form-error" role="alert"></div><button class="btn dark" type="submit">Apply ${icon('arrow')}</button><p class="helper">Your name, selected skills, and message will be shared with the opportunity owner and management.</p></form>`}`)}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();if($('#modal').open)$('#modal').close();go(a.pathname+a.search);return}const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{if(d.role){authRole=d.role;history.replaceState({},'','/login?role='+authRole+(loginDestination()?'&next='+encodeURIComponent(loginDestination()):''));$('#main').innerHTML=authPage()}if(d.filter){filter=d.filter;$('#opportunity-list').innerHTML=filteredOpportunities();document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter))}if(d.opportunity)showOpportunity(d.opportunity);if(d.inviteStudent){const s=directory.find(x=>x.id===d.inviteStudent),mine=opportunities.filter(o=>(o.owner===user.id||user.role==='management')&&o.status==='open'&&(!o.deadline||o.deadline>=new Date().toISOString().slice(0,10)));modal(`<h3>Invite ${esc(s.name)}</h3>${mine.length?`<form id="student-invite-form" data-student="${s.id}"><label class="field">Choose an opportunity<select name="opportunity">${mine.map(o=>`<option value="${o.id}">${esc(o.title)}</option>`).join('')}</select></label>${field('Your message','message','textarea','','required minlength="10" maxlength="1000" placeholder="Tell them why this might be a good opportunity to explore."')}<div class="form-error" role="alert"></div><button class="btn dark" type="submit">Send in-app invitation ${icon('arrow')}</button></form>`:`<p>Create an open opportunity first, then invite students to it.</p><div style="margin-top:20px">${link('/opportunities/new','Create opportunity')}</div>`}`)}if(d.suggest){b.disabled=true;const r=await api(`/opportunities/${d.suggest}/suggest`,'POST',{});toast(r.notified?`Suggested to ${r.notified} matching students.`:'All currently matching students have already been notified.');b.disabled=false}if(d.toggleOpportunity){await api(`/opportunities/${d.toggleOpportunity}/status`,'POST',{status:d.status});$('#modal').close();await render();toast('Opportunity updated.')}if(d.action==='close')$('#modal').close();if(d.action==='auth-toggle'){authMode=authMode==='login'?'register':'login';$('#main').innerHTML=authPage()}if(d.action==='logout'){await api('/logout','POST',{});user=null;clearAccountData();announceSession();go('/')}if(d.action==='read-all'){await api('/notifications/read','POST',{});await render();toast('All updates marked as read.')}if(d.action==='rotate-code'){const r=await api('/join-code/rotate','POST',{});management.joinCode=r.joinCode;await render();toast('Student join code replaced.')}if(d.action==='retry')await render();if(d.action==='save-suggestions'){const choices=[...document.querySelectorAll('input[name="suggested"]:checked')].map(x=>x.value);user=(await api('/profile','PUT',{...user,skills:[...new Set([...user.skills,...choices])]})).user;toast('Selected skills added to your profile.');go('/profile')}}catch(err){toast(err.message);b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search-opportunities'){search=e.target.value;$('#opportunity-list').innerHTML=filteredOpportunities()}if(e.target.id==='search-students')$('#student-list').innerHTML=studentCards(e.target.value)});
document.addEventListener('change',async e=>{if(e.target.dataset.review){const id=e.target.dataset.review,old=applications.find(a=>a.id===id)?.status;try{await api('/applications/'+id,'PUT',{status:e.target.value});applications.find(a=>a.id===id).status=e.target.value;toast('Review saved. The student has been notified.')}catch(err){e.target.value=old;toast(err.message)}}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),d=Object.fromEntries(fd),button=f.querySelector('button[type="submit"]'),err=f.querySelector('.form-error');if(err)err.textContent='';if(button){button.disabled=true;button.dataset.original=button.innerHTML;button.textContent='Working…'}try{switch(f.id){case'setup-form':user=(await api('/setup','POST',d)).user;config=await api('/config');announceSession();await go('/management');break;case'auth-form':user=(await api(authMode==='register'?'/register':'/login','POST',{...d,role:authRole})).user;announceSession();await go(loginDestination()||(user.role==='student'&&!user.skills.length?'/profile':'/'));break;case'profile-form':user=(await api('/profile','PUT',{...d,skills:fd.getAll('skills'),discoverable:!!d.discoverable})).user;await render();toast('Profile saved. Your skill matches are up to date.');break;case'opportunity-form':{const r=await api('/opportunities','POST',{...d,skills:fd.getAll('skills')});go('/opportunities');toast(`Published. ${r.notified} matching students received a suggestion.`);break}case'apply-form':await api(`/opportunities/${f.dataset.id}/apply`,'POST',d);$('#modal').close();await render();toast('Application sent to the opportunity owner.');break;case'staff-invite-form':{const r=await api('/invitations','POST',d);$('#invitation-result').innerHTML=`<div class="result"><h3>Invitation ready</h3><p>Share this code privately with ${esc(r.email)}. No email has been sent.</p><code class="join-code">${esc(r.code)}</code><p class="helper">Use the ${esc(r.role)} create-account screen. Expires in 48 hours.</p></div>`;break}case'student-invite-form':{const r=await api(`/opportunities/${d.opportunity}/invite`,'POST',{student:f.dataset.student,message:d.message});$('#modal').close();toast(r.notified?'Invitation delivered to the student inbox.':'This student has already been invited.');break}case'discover-form':{const r=await api('/discover','POST',{answers:d.answers,useAI:!!d.useAI});$('#discovery-result').innerHTML=`<div class="result"><span class="eyebrow">${r.mode==='ai'?'AI-ASSISTED EXPLORATION':'GUIDED KEYWORD SUGGESTIONS'}</span><h3>A few directions to explore.</h3><p>${esc(r.note)}</p><div class="skill-options" style="margin:20px 0">${r.skills.map(s=>`<label><input type="checkbox" name="suggested" value="${esc(s)}" checked><span>${esc(s)}</span></label>`).join('')}</div>${r.skills.length?'<button class="btn dark" data-action="save-suggestions">Add selected skills to my profile</button>':link('/profile','Choose skills myself')}</div>`;break}}}catch(error){if(err)err.textContent=error.message;else toast(error.message)}finally{if(button){button.disabled=false;button.innerHTML=button.dataset.original}}});
window.addEventListener('popstate',()=>{filter='All';search='';render()});
window.addEventListener('focus',reconcileSession);
window.addEventListener('pageshow',event=>{if(event.persisted)reconcileSession()});
window.addEventListener('storage',event=>{if(event.key==='unseen-session-change')reconcileSession()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')reconcileSession()});
async function start(){await render()}start();
